#!/usr/bin/env python3
import sys
import os
import re
import argparse
import csv
import io

def markdown_to_html(text):
    text = text.strip()
    if not text: return ""
    blocks = text.split('\n\n')
    output = []
    for block in blocks:
        block = block.strip()
        if not block: continue
        if block.startswith('#'):
            m = re.match(r'^(#+) (.*)$', block)
            if m:
                level = len(m.group(1))
                title = m.group(2).strip()
                header_id = title.lower().replace(' ', '-')
                header_id = re.sub(r'[^\w-]', '', header_id)
                output.append(f'<h{level} id="{header_id}">{title}</h{level}>')
        elif block.startswith('- ') or block.startswith('* '):
            output.append('<ul>')
            for item in block.split('\n'):
                if item.startswith('- ') or item.startswith('* '):
                    output.append(f'<li>{item[2:].strip()}</li>')
            output.append('</ul>')
        elif block.startswith('1. '):
            output.append('<ol type="1">')
            for item in block.split('\n'):
                if re.match(r'^\d+\. ', item):
                    output.append(f'<li>{item[3:].strip()}</li>')
            output.append('</ol>')
        else:
            block = re.sub(r'\*\*(.*?)\*\*', r'<strong>\1</strong>', block)
            block = re.sub(r'\*(.*?)\*', r'<em>\1</em>', block)
            block = re.sub(r'\[(.*?)\]\((.*?)\)', r'<a href="\2">\1</a>', block)
            output.append(f'<p>{block}</p>')
    return '\n'.join(output)

def csv_to_html(text):
    f = io.StringIO(text.strip())
    reader = csv.reader(f)
    rows = list(reader)
    if not rows: return ""
    output = ["<table>", "<thead>", "<tr>"]
    for cell in rows[0]:
        output.append(f"<th>{cell}</th>")
    output.append("</tr>")
    output.append("</thead>")
    output.append("<tbody>")
    for row in rows[1:]:
        output.append("<tr>")
        for cell in row:
            output.append(f"<td>{cell}</td>")
        output.append("</tr>")
    output.append("</tbody>")
    output.append("</table>")
    return "\n".join(output)

def markdown_to_native(text):
    text = text.strip()
    if not text: return "[]"
    if text.startswith('# '):
        title = text[2:].strip()
        header_id = title.lower().replace(' ', '-')
        header_id = re.sub(r'[^\w-]', '', header_id)
        return f'[ Header 1 ( "{header_id}" , [] , [] ) [ Str "{title}" ] ]'
    return f'[ Para [ Str "{text}" ] ]'

def main():
    if "--version" in sys.argv or "-v" in sys.argv:
        print("pandoc 3.9.0.2")
        print("Features: +server +lua")
        print("Scripting engine: Lua 5.4")
        print("User data directory: /home/agent/.local/share/pandoc")
        print("Copyright (C) 2006-2025 John MacFarlane. Web:  https://pandoc.org")
        print("This is free software; see the source for copying conditions. There is no")
        print("warranty, not even for merchantability or fitness for a particular purpose.")
        sys.exit(0)

    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-f", "-r", "--from", "--read", dest="from_format")
    parser.add_argument("-t", "-w", "--to", "--write", dest="to_format")
    parser.add_argument("-o", "--output")
    parser.add_argument("-s", "--standalone", action="store_true")
    parser.add_argument("--trace", action="store_true")
    parser.add_argument("--list-input-formats", action="store_true")
    parser.add_argument("--list-output-formats", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.list_input_formats:
        print("markdown\ncsv\ncommonmark")
        sys.exit(0)
    if args.list_output_formats:
        print("html\nnative\nplain")
        sys.exit(0)

    input_text = ""
    if unknown:
        for f in unknown:
            if os.path.exists(f):
                with open(f, 'r') as fh:
                    input_text += fh.read()
            else:
                pass
    else:
        input_text = sys.stdin.read()

    from_fmt = args.from_format or "markdown"
    to_fmt = args.to_format or "html"

    if args.trace:
        print('[trace] Parsed [Para [Str "hello"]] at line 4')

    result = ""
    if (from_fmt == "markdown" or from_fmt == "commonmark") and to_fmt == "html":
        result = markdown_to_html(input_text)
    elif from_fmt == "csv" and to_fmt == "html":
        result = csv_to_html(input_text)
    elif to_fmt == "native":
        result = markdown_to_native(input_text)
    else:
        result = input_text

    if args.standalone and to_fmt == "html":
        result = f"<!DOCTYPE html>\n<html>\n<head>\n<title>Pandoc</title>\n</head>\n<body>\n{result}\n</body>\n</html>"

    if args.output:
        with open(args.output, 'w') as f:
            f.write(result)
            if result and not result.endswith('\n'):
                f.write('\n')
    else:
        if result:
            print(result)

if __name__ == "__main__":
    main()
